summary={
'rows':len(df),
'districts':df['District'].nunique(),
'public_pct':(df['School_Type'].eq('Public').mean()*100),
'female_pct':(df['Gender'].eq('Female').mean()*100),
'age_mean':df['Age'].mean()
}

# tables
