    excellent_rate=('HSC_Result',lambda s:(s>=4.5).mean()*100),
    at_risk_rate=('HSC_Result',lambda s:(s<3.0).mean()*100),
    n=('Student_ID','count')
)

parent=df.groupby('Parent_Education',as_index=False).agg(
    avg_hsc=('HSC_Result','mean'),
    avg_income=('Family_Income_BDT','mean'),
    excellent_rate=('HSC_Result',lambda s:(s>=4.5).mean()*100),
    n=('Student_ID','count')
).sort_values('avg_hsc',ascending=False)

internet=df.groupby('Internet_Access',as_index=False).agg(
    avg_hsc=('HSC_Result','mean'),
    excellent_rate=('HSC_Result',lambda s:(s>=4.5).mean()*100),
    at_risk_rate=('HSC_Result',lambda s:(s<3.0).mean()*100),
    avg_attendance=('Attendance','mean'),
    n=('Student_ID','count')
)

tuition=df.groupby('Private_Tuition',as_index=False).agg(
    avg_hsc=('HSC_Result','mean'),
    excellent_rate=('HSC_Result',lambda s:(s>=4.5).mean()*100),
    at_risk_rate=('HSC_Result',lambda s:(s<3.0).mean()*100),
